WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, id) AS rn FROM employees QUALIFY rn = 1) SELECT CASE WHEN salary >= 129000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, dept_id, APPROX_PERCENTILE(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, ROUND(AVG(salary), 2) AS avg_salary, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN job_title = 'Director' THEN 1 END), 0), 2) AS salary_per_director FROM latest GROUP BY GROUPING SETS ((CASE WHEN salary >= 129000 THEN 'HIGH' ELSE 'LOW' END, dept_id), (CASE WHEN salary >= 129000 THEN 'HIGH' ELSE 'LOW' END));
